import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';

const ChatPanel = ({ socket }) => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [onlineUsers, setOnlineUsers] = useState(0);
  const { user } = useAuth();
  const messagesEndRef = useRef(null);

  // Fetch initial messages
  useEffect(() => {
    const fetchInitialData = async () => {
      try {
        const [messagesRes, onlineRes] = await Promise.all([
          fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/chat/messages`),
          fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/chat/online`)
        ]);

        if (messagesRes.ok) {
          const messagesData = await messagesRes.json();
          setMessages(messagesData);
        }

        if (onlineRes.ok) {
          const onlineData = await onlineRes.json();
          setOnlineUsers(onlineData.count);
        }
      } catch (error) {
        console.error('Error fetching initial chat data:', error);
      }
    };

    fetchInitialData();

    // Listen for online user count updates
    if (socket) {
      socket.on('onlineCountUpdate', (data) => {
        setOnlineUsers(data.count);
      });
    }

    return () => {
      if (socket) {
        socket.off('onlineCountUpdate');
      }
    };
  }, [socket]);

  // Listen for new messages
  useEffect(() => {
    if (socket) {
      socket.on('chatMessage', (data) => {
        setMessages(prev => [...prev, data]);
      });

      return () => {
        socket.off('chatMessage');
      };
    }
  }, [socket]);

  // Scroll to bottom when messages change
  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!inputMessage.trim()) return;

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/chat/send`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ message: inputMessage })
      });

      if (response.ok) {
        setInputMessage('');
      } else {
        const errorData = await response.json();
        alert(errorData.message || 'Failed to send message');
      }
    } catch (error) {
      console.error('Error sending message:', error);
      alert('Error sending message');
    }
  };

  return (
    <div className="chat-panel">
      <div className="chat-header">
        <h3>Chat</h3>
        <span className="online-users">{onlineUsers} online</span>
      </div>

      <div className="chat-messages">
        {messages.map((msg) => (
          <div key={msg.id || msg._id} className="chat-message">
            <img 
              src={msg.avatar || '/default-avatar.png'} 
              alt="Avatar" 
              className="message-avatar"
              onError={(e) => {
                e.target.src = '/default-avatar.png';
              }}
            />
            <div className="message-content">
              <div className="message-header">
                <span className="message-username">{msg.username || msg.displayName}</span>
                <span className="message-time">
                  {new Date(msg.timestamp || msg.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>
              <div className="message-text">{msg.message}</div>
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form className="chat-input-form" onSubmit={handleSubmit}>
        <input
          type="text"
          className="chat-input"
          value={inputMessage}
          onChange={(e) => setInputMessage(e.target.value)}
          placeholder="Type a message..."
          maxLength={280}
        />
        <button type="submit" className="send-button">Send</button>
      </form>
    </div>
  );
};

export default ChatPanel;
